changeSet.sql:
CREATE TABLE IF NOT EXISTS credesal_loan_portfolio_snapshot ( snapshot_date DATE NOT NULL, loan_id BIGINT NOT NULL REFERENCES m_loan(id) ON DELETE CASCADE, office_id BIGINT NOT NULL REFERENCES m_office(id), loan_product_id BIGINT NOT NULL REFERENCES m_product_loan(id), currency_code VARCHAR(3) NOT NULL, loan_status VARCHAR(20) NOT NULL, legal_status VARCHAR(40), grant_date DATE NOT NULL, maturity_date DATE NOT NULL, term_days INTEGER NOT NULL, days_past_due INTEGER NOT NULL, risk_classification_id VARCHAR(16) NOT NULL, risk_classification VARCHAR(16) NOT NULL, risk_order SMALLINT NOT NULL, portfolio_status CHAR(1) NOT NULL, disbursed_amount NUMERIC(19, 6) NOT NULL, principal_balance NUMERIC(19, 6) NOT NULL, overdue_principal NUMERIC(19, 6) NOT NULL, overdue_interest NUMERIC(19, 6) NOT NULL, source_close_id VARCHAR(64), created_on TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (snapshot_date, loan_id), CHECK (term_days >= 0), CHECK (days_past_due >= 0), CHECK (risk_order > 0), CHECK (portfolio_status IN ('1', '2')), CHECK (disbursed_amount >= 0.00), CHECK (principal_balance >= 0.00), CHECK (overdue_principal >= 0.00), CHECK (overdue_interest >= 0.00) );
CREATE INDEX IF NOT EXISTS idx_credesal_loan_portfolio_snapshot_scope ON credesal_loan_portfolio_snapshot (snapshot_date, office_id, loan_product_id);
INSERT INTO stretchy_report ( report_name, report_type, report_subtype, report_category, report_sql, description, core_report, use_report, self_service_user_report ) VALUES ( 'Detalle de Saldos de Préstamos y Morosidad', 'Table', NULL, 'Loan', $report$ WITH selected_offices AS ( SELECT office_under.id FROM m_office selected_office JOIN m_office office_under ON office_under.hierarchy LIKE selected_office.hierarchy || '%' WHERE selected_office.id = CAST('${officeId}' AS BIGINT) AND office_under.hierarchy LIKE '${currentUserHierarchy}' || '%' ), resolved_cutoff AS ( SELECT MAX(snapshot.snapshot_date) AS snapshot_date FROM credesal_loan_portfolio_snapshot snapshot WHERE snapshot.snapshot_date >= CAST('${startDate}' AS DATE) AND snapshot.snapshot_date <= CAST('${endDate}' AS DATE) ), portfolio AS ( SELECT snapshot.snapshot_date, CASE WHEN snapshot.term_days <= 366 THEN 1 ELSE 2 END AS term_order, CASE WHEN snapshot.term_days <= 366 THEN 'CORTO PLAZO' ELSE 'LARGO PLAZO' END AS term_type, office.hierarchy AS office_hierarchy, office.id AS office_id, office.name AS office_name, product.id AS product_id, product.name AS credit_line, snapshot.risk_classification_id, snapshot.risk_classification, snapshot.risk_order, snapshot.disbursed_amount, snapshot.principal_balance, snapshot.overdue_principal, snapshot.overdue_interest, snapshot.portfolio_status FROM credesal_loan_portfolio_snapshot snapshot JOIN resolved_cutoff cutoff ON cutoff.snapshot_date = snapshot.snapshot_date JOIN selected_offices selected ON selected.id = snapshot.office_id JOIN m_office office ON office.id = snapshot.office_id JOIN m_product_loan product ON product.id = snapshot.loan_product_id WHERE snapshot.loan_status = 'ACTIVE' AND snapshot.legal_status IS NULL AND snapshot.currency_code = 'USD' ), classification_rows AS ( SELECT term_order, term_type, office_hierarchy, office_id, office_name, product_id, credit_line, risk_order, risk_classification, COUNT(*) AS loan_count, COUNT(*) FILTER (WHERE risk_classification_id <> '1') AS loans_in_arrears_count, SUM(disbursed_amount) AS disbursed_amount, SUM(principal_balance) AS principal_balance, SUM(principal_balance) FILTER (WHERE risk_classification_id <> '1') AS affected_portfolio, SUM(overdue_principal) AS overdue_principal, SUM(overdue_interest) AS overdue_interest, SUM(principal_balance) FILTER (WHERE portfolio_status = '1') AS current_portfolio, SUM(principal_balance) FILTER (WHERE portfolio_status = '2') AS overdue_portfolio FROM portfolio GROUP BY term_order, term_type, office_hierarchy, office_id, office_name, product_id, credit_line, risk_order, risk_classification ), display_rows AS ( SELECT term_order, term_type, office_hierarchy, office_id, office_name, product_id, credit_line, 1 AS row_order, risk_order, 'CLASIFICACION'::VARCHAR AS row_type, risk_classification AS classification, loan_count, loans_in_arrears_count, disbursed_amount, principal_balance, COALESCE(affected_portfolio, 0.00) AS affected_portfolio, overdue_principal, overdue_interest, COALESCE(current_portfolio, 0.00) AS current_portfolio, COALESCE(overdue_portfolio, 0.00) AS overdue_portfolio FROM classification_rows
UNION ALL
SELECT term_order, term_type, office_hierarchy, office_id, office_name, product_id, credit_line, 2, 999, 'TOTAL_LINEA', NULL, SUM(loan_count), SUM(loans_in_arrears_count), SUM(disbursed_amount), SUM(principal_balance), SUM(affected_portfolio), SUM(overdue_principal), SUM(overdue_interest), SUM(current_portfolio), SUM(overdue_portfolio) FROM classification_rows GROUP BY term_order, term_type, office_hierarchy, office_id, office_name, product_id, credit_line
UNION ALL
SELECT term_order, term_type, office_hierarchy, office_id, office_name, NULL, NULL, 3, 999, 'TOTAL_SUCURSAL', NULL, SUM(loan_count), SUM(loans_in_arrears_count), SUM(disbursed_amount), SUM(principal_balance), SUM(affected_portfolio), SUM(overdue_principal), SUM(overdue_interest), SUM(current_portfolio), SUM(overdue_portfolio) FROM classification_rows GROUP BY term_order, term_type, office_hierarchy, office_id, office_name
UNION ALL
SELECT term_order, term_type, '~~~~', NULL, NULL, NULL, NULL, 4, 999, 'TOTAL_PLAZO', NULL, SUM(loan_count), SUM(loans_in_arrears_count), SUM(disbursed_amount), SUM(principal_balance), SUM(affected_portfolio), SUM(overdue_principal), SUM(overdue_interest), SUM(current_portfolio), SUM(overdue_portfolio) FROM classification_rows GROUP BY term_order, term_type
UNION ALL
SELECT 3, NULL, '~~~~', NULL, NULL, NULL, NULL, 5, 999, 'TOTAL_GENERAL', NULL, SUM(loan_count), SUM(loans_in_arrears_count), SUM(disbursed_amount), SUM(principal_balance), SUM(affected_portfolio), SUM(overdue_principal), SUM(overdue_interest), SUM(current_portfolio), SUM(overdue_portfolio) FROM classification_rows HAVING COUNT(*) > 0 ), grand_total AS ( SELECT COALESCE(SUM(principal_balance), 0.00) AS principal_balance FROM classification_rows ) SELECT ROW_NUMBER() OVER ( ORDER BY row.term_order, row.office_hierarchy COLLATE "C", row.product_id NULLS LAST, row.row_order, row.risk_order ) AS "Orden", row.row_type AS "Tipo Fila", row.term_type AS "Tipo Plazo", row.office_id AS "Id Oficina", row.office_name AS "Sucursal", row.product_id AS "Id Línea Crédito", row.credit_line AS "Línea Crédito", row.classification AS "CLSF", row.loan_count AS "Cantidad Préstamos", row.loans_in_arrears_count AS "Cantidad Préstamos en Mora", ROUND(row.disbursed_amount, 2) AS "Monto Desembolsado", ROUND(row.principal_balance, 2) AS "Saldo Capital", ROUND(row.affected_portfolio, 2) AS "Cartera Afectada", ROUND(row.overdue_principal, 2) AS "Capital Vencido", ROUND(row.overdue_interest, 2) AS "Interés Vencido", ROUND(row.current_portfolio, 2) AS "Cartera Vigente", ROUND(row.overdue_portfolio, 2) AS "Cartera Vencida", CASE WHEN total.principal_balance = 0.00 THEN 0.0000 ELSE ROUND(row.principal_balance * 100.0 / total.principal_balance, 4) END AS "Porcentaje Cartera %", CASE WHEN total.principal_balance = 0.00 THEN 0.0000 ELSE ROUND(row.overdue_principal * 100.0 / total.principal_balance, 4) END AS "Porcentaje Vencido %", cutoff.snapshot_date AS "Fecha Corte", TO_CHAR(CAST('${startDate}' AS DATE), 'YYYY-MM') AS "Período" FROM display_rows row CROSS JOIN grand_total total CROSS JOIN resolved_cutoff cutoff ORDER BY row.term_order, row.office_hierarchy COLLATE "C", row.product_id NULLS LAST, row.row_order, row.risk_order; $report$, 'Cartera y morosidad en USD por plazo, sucursal, línea de crédito y clasificación al último cierre disponible del período.', FALSE, TRUE, FALSE ) ON CONFLICT (report_name) DO UPDATE SET report_type = EXCLUDED.report_type, report_subtype = EXCLUDED.report_subtype, report_category = EXCLUDED.report_category, report_sql = EXCLUDED.report_sql, description = EXCLUDED.description, core_report = EXCLUDED.core_report, use_report = EXCLUDED.use_report, self_service_user_report = EXCLUDED.self_service_user_report;
DELETE FROM stretchy_report_parameter WHERE report_id = ( SELECT id FROM stretchy_report WHERE report_name = 'Detalle de Saldos de Préstamos y Morosidad' );
INSERT INTO stretchy_report_parameter ( report_id, parameter_id, report_parameter_name ) SELECT report.id, parameter.id, parameter.parameter_variable FROM stretchy_report report CROSS JOIN stretchy_parameter parameter WHERE report.report_name = 'Detalle de Saldos de Préstamos y Morosidad' AND parameter.parameter_name IN ('OfficeIdSelectOne', 'startDateSelect', 'endDateSelect');
DO $validation$ BEGIN IF ( SELECT COUNT(*) FROM stretchy_report_parameter usage JOIN stretchy_report report ON report.id = usage.report_id WHERE report.report_name = 'Detalle de Saldos de Préstamos y Morosidad' AND usage.report_parameter_name IN ('officeId', 'startDate', 'endDate') ) <> 3 THEN RAISE EXCEPTION 'Detalle de Saldos de Préstamos y Morosidad requires officeId, startDate and endDate'; END IF; END $validation$;
INSERT INTO m_permission ( grouping, code, entity_name, action_name, can_maker_checker ) SELECT 'report', 'READ_Detalle de Saldos de Préstamos y Morosidad', 'Detalle de Saldos de Préstamos y Morosidad', 'READ', FALSE WHERE NOT EXISTS ( SELECT 1 FROM m_permission WHERE code = 'READ_Detalle de Saldos de Préstamos y Morosidad' );
